// auth.py → get_current_user()
// Firebase Admin SDK: admin.auth().verify_id_token(token)
// Extrae del token: uid, email, role (custom claim)
// Lanza 401 si token inválido o expirado
const bearer = items[0].json.headers?.authorization ?? '';
const token = bearer.replace('Bearer ', '');
const decoded = await admin.auth().verifyIdToken(token);
return [{ json: { uid: decoded.uid, email: decoded.email, role: decoded.role ?? null,
  message: items[0].json.body.message, chat_id: items[0].json.body.chat_id } }];

// firestore_service.py → get_chat_messages(uid, chat_id)
// Colección: sessions/{uid}/chats/{chat_id} → messages[]
// Retorna lista [{role, content, tokens, timestamp}] para contexto del LLM
const { uid, chat_id, message } = $json;
const doc = await db.collection('sessions').doc(uid)
  .collection('chats').doc(chat_id).get();
const history = doc.data()?.messages ?? [];
return [{ json: { uid, chat_id, message, history } }];

// firestore_service.py → save_chat_message()
// Guarda mensaje usuario (tokens=0) + respuesta asistente (tokens=total)
// Actualiza: message_count, preview, created_at en el documento del chat
const reply = $json.choices[0].message.content;
const tokens = $json.usage?.total_tokens ?? 0;
const { uid, chat_id, message } = $('📚 Obtener Historial Firestore').first().json;
await saveMsg(uid, chat_id, 'user', message, 0);
await saveMsg(uid, chat_id, 'assistant', reply, tokens);
return [{ json: { reply, chat_id, tokens_used: tokens, used_search: true } }];

// backend/main.py → _download_img() con httpx.AsyncClient
// Descarga concurrente de hasta 8 URLs candidatas con asyncio.gather()
// Filtros: content-type image/* · tamaño < 4MB · excluye SVG
// Resultado: [{ title, data: 'data:image/jpeg;base64,...' }]
const urls1 = $input.all()[0].json.images ?? [];
const urls2 = $input.all()[1].json.images ?? [];
const allUrls = [...urls1, ...urls2].slice(0, 8);
const downloaded = await Promise.all(allUrls.map(url => downloadBase64(url)));
const images = downloaded.filter(Boolean).slice(0, 6);
return [{ json: { images, destination: $('GET /images/{destination}').first().json.destination } }];

// backend/main.py → _img_cache[key] = (result, time.time())
// Estructura: { plaza: img0, top: img1, extras: [img2..img5] }
// TTL: 86400 s · Primera consulta ~8-14s · Subsiguientes ~1-2s
const imgs = $json.images;
const result = { plaza: imgs[0] ?? null, top: imgs[1] ?? null, extras: imgs.slice(2) };
storeCache($json.destination, result);
return [{ json: result }];

// backend/main.py → _build_route_map_sync() en thread pool executor
// staticmap + OSM tiles: a.tile.openstreetmap.org/{z}/{x}/{y}.png
// Dibuja: Line azul (#1565A0 px4) · CircleMarker A azul (px16) · B rojo (px16)
// PIL.Image.LANCZOS (Pillow 10+ compat)
const route = $json.routes?.[0];
const coords = route?.geometry?.coordinates ?? [];
const dist_m = Math.round(route?.distance ?? 0);
const dur_min = Math.round((route?.duration ?? 0) / 60);
const imgBytes = renderOSMMap(640, 340, coords, fromXY, toXY);
return [{ json: { image: 'data:image/png;base64,' + btoa(imgBytes), from_label: $json.from_label,
  to_label: $json.to_label, top_name: $json.top_name, dist_m, dur_min } }];

// firestore_service.py → get_chat_messages(uid, chat_id)
// Prepara texto de conversación para prompt de extracción
// Trunca cada mensaje a 1500 chars para no exceder context window
const { uid, chat_id } = $json;
const messages = await getFirestoreMsgs(uid, chat_id);
const conv = messages.map(m => `${m.role === 'user' ? 'Usuario' : 'Asistente'}: ${(m.content ?? '').slice(0, 1500)}`).join('\n\n');
if (!conv) throw new Error('Chat vacío o no encontrado');
return [{ json: { conversation: conv } }];

