// agent.py → generate_summary()
// Limpia markdown fences: ```json ... ```
// Extrae objeto JSON con regex {[\s\S]*}
// Valida y completa claves faltantes con 'No disponible'
const raw = ($json.choices[0]?.message?.content ?? '').trim();
const cleaned = raw.replace(/^```(?:json)?\s*/m,'').replace(/\s*```\s*$/m,'');
const match = cleaned.match(/\{[\s\S]*\}/);
if (!match) throw new Error('Mistral no devolvió JSON válido');
const result = JSON.parse(match[0]);
const base = { destino:'No disponible', clima:{descripcion:'',temperatura:'',recomendacion:''},
  costos:{transporte:{economico:'',comodo:''},hospedaje:{economico:'',comodo:''},
  alimentacion:{economico:'',comodo:''},tours:{economico:'',comodo:''}}, lugares:[], consejos:[] };
return [{ json: Object.assign(base, result) }];
